#include <vector>
#include <cstdlib>

using namespace std;

class Solution {
    vector<int> prefix;
    int total = 0;

public:
    Solution(vector<int>& w) {
        for (int weight : w) {
            total += weight;
            prefix.push_back(total);
        }
    }

    int pickIndex() {
        int target = rand() % total;
        return upper_bound(prefix.begin(), prefix.end(), target) - prefix.begin();
    }
};
